44	class MetaAssetCreationService {
45	  /**
46	   * Create a new Meta ad account for a client connection
47	   *
48	   * @param connectionId - Client connection ID
49	   * @param businessId - Meta Business Manager ID
50	   * @param params - Ad account creation parameters
51	   * @param userEmail - User email for audit logging
52	   * @param agencyId - Agency ID for audit logging
53	   * @returns Created ad account details
54	   */
55	  async createAdAccount(
56	    connectionId: string,
57	    businessId: string,
58	    params: CreateAdAccountParams,
59	    userEmail: string,
60	    agencyId: string
61	  ): Promise<{ data: CreatedAdAccount | null; error: { code: string; message: string; details?: any } | null }> {
62	    try {
63	      logger.info('Creating Meta ad account', {
64	        connectionId,
65	        businessId,
66	        accountName: params.name,
67	        currency: params.currency,
68	      });
69	
70	      // Step 1: Get the platform authorization for this connection
71	      const platformAuth = await prisma.platformAuthorization.findUnique({
72	        where: {
73	          connectionId_platform: {
74	            connectionId,
75	            platform: 'meta',
76	          },
77	        },
78	      });
79	
80	      if (!platformAuth) {
81	        return {
82	          data: null,
83	          error: {
84	            code: 'AUTHORIZATION_NOT_FOUND',
85	            message: 'Meta authorization not found for this connection',
86	          },
87	        };
88	      }
89	
90	      // Step 2: Check if authorization is active
91	      if (platformAuth.status !== 'active') {
92	        return {
93	          data: null,
94	          error: {
95	            code: 'AUTHORIZATION_INACTIVE',
96	            message: 'Meta authorization is not active',
97	          },
98	        };
99	      }
100	
101	      // Step 3: Retrieve tokens from Infisical (NEVER from database)
102	      let tokens;
103	      try {
104	        tokens = await infisical.getOAuthTokens(platformAuth.secretId);
105	      } catch (tokenError) {
106	        logger.error('Failed to retrieve Meta tokens from Infisical', {
107	          connectionId,
108	          secretId: platformAuth.secretId,
109	          error: tokenError,
110	        });
111	        return {
112	          data: null,
113	          error: {
114	            code: 'TOKEN_NOT_FOUND',
115	            message: 'OAuth tokens not found in secure storage',
116	          },
117	        };
118	      }
119	
120	      if (!tokens || !tokens.accessToken) {
121	        return {
122	          data: null,
123	          error: {
124	            code: 'TOKEN_NOT_FOUND',
125	            message: 'OAuth tokens not found in secure storage',
126	          },
127	        };
128	      }
129	
130	      // Step 4: Check if token is expired
131	      if (tokens.expiresAt && new Date(tokens.expiresAt) < new Date()) {
132	        return {
133	          data: null,
134	          error: {
135	            code: 'TOKEN_EXPIRED',
136	            message: 'Your authorization has expired. Please reconnect your Meta account.',
137	          },
138	        };
139	      }
140	
141	      // Step 5: Create ad account via Meta API
142	      const createdAccount = await metaConnector.createAdAccount(
143	        tokens.accessToken,
144	        businessId,
145	        params
146	      );
147	
148	      logger.info('Meta ad account created successfully', {
149	        connectionId,
150	        accountId: createdAccount.id,
151	        accountName: createdAccount.name,
152	      });
153	
154	      // Step 6: Update connection metadata with created asset
155	      const connection = await prisma.clientConnection.findUnique({
156	        where: { id: connectionId },
157	      });
158	
159	      if (connection) {
160	        const currentGrantedAssets = (connection.grantedAssets as any) || {};
161	        const createdAdAccounts = currentGrantedAssets.meta?.createdAdAccounts || [];
162	
163	        await prisma.clientConnection.update({
164	          where: { id: connectionId },
165	          data: {
166	            grantedAssets: {
167	              ...currentGrantedAssets,
168	              meta: {
169	                ...(currentGrantedAssets.meta || {}),
170	                createdAdAccounts: [
171	                  ...createdAdAccounts,
172	                  {
173	                    id: createdAccount.id,
174	                    accountId: createdAccount.accountId,
175	                    name: createdAccount.name,
176	                    currency: createdAccount.currency,
177	                    timezoneId: createdAccount.timezoneId,
178	                    createdAt: new Date().toISOString(),
179	                  },
180	                ],
181	              },
182	            },
183	          },
184	        });
185	      }
186	
187	      // Step 7: Create audit log
188	      await auditService.createAuditLog({
189	        agencyId,
190	        userEmail,
191	        action: 'META_AD_ACCOUNT_CREATED',
192	        resourceType: 'client_connection',
193	        resourceId: connectionId,
194	        metadata: {
195	          platform: 'meta',
196	          businessId,
197	          accountId: createdAccount.id,
198	          accountName: createdAccount.name,
199	          currency: createdAccount.currency,
200	          timezoneId: createdAccount.timezoneId,
201	        },
202	      });
203	
204	      return { data: createdAccount, error: null };
205	    } catch (error) {
206	      logger.error('Failed to create Meta ad account', {
207	        connectionId,
208	        businessId,
209	        error: error instanceof Error ? error.message : String(error),
210	      });
211	
212	      // Check for specific Meta API errors
213	      const errorMessage = error instanceof Error ? error.message : String(error);
214	
215	      if (errorMessage.includes('permission') || errorMessage.includes('scope')) {
216	        return {
217	          data: null,
218	          error: {
219	            code: 'INSUFFICIENT_PERMISSIONS',
220	            message: 'Your Meta account does not have permission to create ad accounts. Please ensure you have ads_management scope.',
221	          },
222	        };
223	      }
224	
225	      if (errorMessage.includes('limit') || errorMessage.includes('maximum')) {
226	        return {
227	          data: null,
228	          error: {
229	            code: 'LIMIT_EXCEEDED',
230	            message: 'You have reached the maximum number of ad accounts for this Business Manager.',
231	          },
232	        };
233	      }
234	
235	      return {
236	        data: null,
237	        error: {
238	          code: 'CREATION_FAILED',
239	          message: `Failed to create ad account: ${errorMessage}`,
240	        },
241	      };
242	    }
243	  }
