27	/**
28	 * Resolve and validate an authorized connection for an access request token
29	 */
30	async function resolveAuthorizedConnection(token: string, connectionId: string) {
31	  const accessRequest = await accessRequestService.getAccessRequestByToken(token);
32	  if (accessRequest.error || !accessRequest.data) {
33	    return {
34	      accessRequest: null,
35	      connection: null,
36	      error: {
37	        code: 'ACCESS_REQUEST_NOT_FOUND',
38	        message: 'Access request not found',
39	      },
40	    };
41	  }
42	
43	  const connection = await prisma.clientConnection.findUnique({
44	    where: { id: connectionId },
45	  });
46	
47	  if (!connection) {
48	    return {
49	      accessRequest: accessRequest.data,
50	      connection: null,
51	      error: {
52	        code: 'CONNECTION_NOT_FOUND',
53	        message: 'Client connection not found',
54	      },
55	    };
56	  }
57	
58	  const isAuthorizedConnection =
59	    connection.accessRequestId === accessRequest.data.id &&
60	    connection.agencyId === accessRequest.data.agencyId;
61	
62	  if (!isAuthorizedConnection) {
63	    return {
64	      accessRequest: accessRequest.data,
65	      connection: null,
66	      error: {
67	        code: 'FORBIDDEN',
68	        message: 'Connection does not belong to this access request',
69	      },
70	    };
71	  }
72	
73	  return {
74	    accessRequest: accessRequest.data,
75	    connection,
76	    error: null,
77	  };
78	}
