80	export async function registerAssetCreationRoutes(fastify: FastifyInstance) {
81	  /**
82	   * Create a new Meta ad account
83	   * POST /api/client/:token/create/meta/ad-account
84	   */
85	  fastify.post('/client/:token/create/meta/ad-account', async (request, reply) => {
86	    const { token } = request.params as { token: string };
87	
88	    // Validate request body
89	    const validated = createAdAccountSchema.safeParse(request.body);
90	    if (!validated.success) {
91	      return sendError(reply, 'VALIDATION_ERROR', 'Invalid request parameters', 400, validated.error.errors,);
92	    }
93	
94	    const { connectionId, businessId, name, currency, timezoneId } = validated.data;
95	
96	    // Resolve and authorize connection
97	    const authContext = await resolveAuthorizedConnection(token, connectionId);
98	    if (authContext.error || !authContext.connection || !authContext.accessRequest) {
99	      const statusCode = authContext.error?.code === 'FORBIDDEN' ? 403 : 404;
100	      return reply.code(statusCode).send({
101	        data: null,
102	        error: authContext.error,
103	      });
104	    }
105	
106	    // Create ad account
107	    const result = await metaAssetCreationService.createAdAccount(
108	      connectionId,
109	      businessId,
110	      { name, currency, timezoneId },
111	      authContext.connection.clientEmail,
112	      authContext.accessRequest.agencyId
113	    );
114	
115	    if (result.error) {
116	      const statusCode =
117	        result.error.code === 'AUTHORIZATION_NOT_FOUND' ||
118	        result.error.code === 'TOKEN_NOT_FOUND'
119	          ? 404
120	          : result.error.code === 'TOKEN_EXPIRED' ||
121	            result.error.code === 'AUTHORIZATION_INACTIVE'
122	          ? 400
123	          : 500;
124	      return reply.code(statusCode).send({
125	        data: null,
126	        error: result.error,
127	      });
128	    }
129	
130	    return reply.send({
131	      data: result.data,
132	      error: null,
133	    });
134	  });
