72	function resolveRequestedTikTokAccessLevel(accessRequest: any): string {
73	  const platforms = Array.isArray(accessRequest?.platforms) ? accessRequest.platforms : [];
74	
75	  for (const group of platforms) {
76	    if (group?.platformGroup !== 'tiktok' || !Array.isArray(group.products)) continue;
77	    const productLevels = group.products
78	      .map((product: any) => product?.accessLevel)
79	      .filter((value: unknown): value is string => typeof value === 'string');
80	
81	    if (productLevels.includes('admin')) return 'admin';
82	    if (productLevels.includes('standard')) return 'standard';
83	    if (productLevels.includes('read_only')) return 'read_only';
84	    if (productLevels.includes('email_only')) return 'email_only';
85	  }
86	
87	  for (const platform of platforms) {
88	    const platformName = platform?.platform;
89	    if (platformName !== 'tiktok' && platformName !== 'tiktok_ads') continue;
90	    if (platform?.accessLevel === 'manage') return 'admin';
91	    if (platform?.accessLevel === 'view_only') return 'read_only';
92	  }
93	
94	  return 'standard';
95	}
